import {
  base,
  jest,
  node,
  react,
  reactNative,
  tailwind,
  typescriptPendingIgnores,
} from '@spudly/eslint-config';

import noClassnameOutsideComponentsPlugin from './eslint-rules/no-classname-outside-components.ts';

// Eciperay's ESLint config. The rule sets live in @spudly/eslint-config,
// extracted from this file's previous 1,237-line version; this file only
// composes the shared exports and keeps the pieces specific to this
// repo's layout:
//   - repo-local ignores (build output, native projects, generated files)
//   - the `node` export's server paths (the package ships rules only, so
//     each consuming repo attaches its own `files:` globs)
//   - the Jest paths the shared export's naming conventions don't cover
//   - sections 1a / 8b / 9 / 9a — path-scoped relaxations
//   - section 10a — the local no-classname-outside-components rule, which
//     stays here until the design-system rule tracked in
//     spudly/design-system#119 exists
export default [
  {
    ignores: [
      '**/node_modules/**',
      '**/dist/**',
      '**/dist-e2e*/**', // Playwright e2e build output (packages/web/playwright.config.ts)
      '**/test-results/**', // Playwright traces/reports
      'packages/app/ios/**',
      'packages/app/android/**',
      'packages/app/__tests__/**',
      'packages/app/env-shim.js', // generated by Metro at start-time; not committed
      'packages/app/env-shim.test.js', // test-only CJS shim for @env; not a test suite
      'packages/app/src/types/*.d.ts', // ambient type declarations only
      'packages/web/src/vite-env.d.ts', // Vite ambient types
      'packages/*/coverage/**', // generated Istanbul/V8 coverage reports
    ],
  },

  // typescript-eslint was the only TypeScript parser in this tree and is
  // uninstalled pending its TypeScript 7 support, so ESLint cannot parse
  // TypeScript at all. Until it returns, .ts/.tsx files are NOT linted —
  // `npm run typecheck` (TS7) is the correctness gate for TS. Plain
  // JS/CJS/MJS files are still linted by the sections below. The shared
  // export carries these ignores; see the @spudly/eslint-config README
  // for the restore path.
  ...typescriptPendingIgnores,

  // Core rules, JS-file re-enables, import-x, unicorn, the CommonJS
  // config-file overrides, the coverage-ignore rule, the eslint-comments
  // discipline, and Prettier last (old sections 1, 1b, 3, 4, 4a, 10, 11,
  // 12-unicorn, 13).
  ...base,

  // React rules on @eslint-react plus react-hooks (old sections 5 and
  // 8c, plus their section-12 additions) and the vendored react-native
  // rules (old section 5). eslint-plugin-react and
  // eslint-plugin-react-native have no ESLint 10 releases — see the
  // @spudly/eslint-config README for the migration notes.
  ...react,
  ...reactNative,

  // Node.js rules (old section 6, plus its section-12 additions). The
  // shared export is rules-only, so this repo attaches its own server
  // paths — the same scope the old section 6 used.
  ...node.map(block => ({
    ...block,
    files: ['packages/server/**/*.ts', 'packages/mcp-server/**/*.ts'],
  })),

  // Jest rules (old section 7, plus its section-12 additions), scoped by
  // the shared export to Jest's naming conventions: test/spec suffixes,
  // jest.setup/jest.env/jest.setupEnv filenames, and __tests__/.
  ...jest,

  // This repo's nonstandard Jest paths, which those conventions don't
  // cover: a root test/ setup file whose name isn't jest.*, and the
  // packages' src/test helper directories. Same blocks, local paths.
  ...jest.map(block => ({
    ...block,
    files: ['test/failOnConsoleError.cjs', 'packages/*/src/test/**/*.ts'],
  })),

  // Tailwind v4 (old sections 8 and 8a applied one identical rule set to
  // the app and web packages; the shared export applies it per
  // component-file extension).
  ...tailwind,

  // ─── 1a. Console allowed — scripts and server bootstrap/migration ──────────
  // console.log is the appropriate output channel for CLI scripts and startup
  // messages. Route handlers and library code must not use console directly.
  {
    files: [
      'scripts/**/*.ts',
      'packages/server/src/server.ts',
      'packages/server/src/db/migrate.ts',
      'packages/mcp-server/src/index.ts',
    ],
    rules: {'no-console': 'off'},
  },

  // ─── 8b. import-x — web/client (Vite workspace resolution) ───────────────
  // A one-repo layout exception: Vite resolves workspace imports in ways
  // that make import-x/no-cycle report false cycles for the web and
  // client packages, so the rule is off for those packages only.
  {
    files: ['packages/web/**/*.{ts,tsx}', 'packages/client/**/*.{ts,tsx}'],
    rules: {'import-x/no-cycle': 'off'},
  },

  // ─── 9. TSX component overrides — relax line limits for JSX ──────────────
  // JSX component functions return multi-line render trees by nature. The
  // 15-line limit applies to pure logic; components get a higher ceiling.
  {
    files: ['packages/app/**/*.tsx', 'packages/web/**/*.tsx'],
    ignores: ['packages/app/**/*.test.tsx', 'packages/web/**/*.test.tsx'],
    rules: {
      // Screen components and forms exceed 65 lines; file-level max-lines still applies
      'max-lines-per-function': 'off',
      'react/no-raw-text': 'off',
    },
  },

  // ─── 9a. App components — custom Text wrappers (PageTitle, ErrorText, etc.) ─
  {
    files: ['packages/app/src/components/**/*.tsx'],
    ignores: ['packages/app/src/components/**/*.test.tsx'],
    rules: {'react-native/no-raw-text': 'off'},
  },

  // ─── 10a. UI — className only inside src/components ───────────────────────
  // Stays local until the design-system rule (spudly/design-system#119)
  // exists; page components must not apply styling directly.
  {
    files: ['packages/app/src/**/*.tsx', 'packages/web/src/**/*.tsx'],
    ignores: ['**/src/components/**', '**/*.test.tsx'],
    plugins: {'eciperay-ui': noClassnameOutsideComponentsPlugin},
    rules: {'eciperay-ui/no-classname-outside-components': 'error'},
  },
];
